}


def set_span_chat_attributes(span: LiveSpan, inputs: dict[str, Any], output: Any):
    if span.span_type not in (SpanType.CHAT_MODEL, SpanType.LLM):
        return

    messages = _parse_inputs_output(inputs, output)
